VID.narration = {"look":{"bar":false},"scenes":[{"dur":7.616,"caps":[[0.5,6.99,"Lecture eleven. Distributed machine learning. How many machines share the work of training one model."]],"warp":[[0,0],[0.5,0.9],[7.616,4]]},{"dur":25.008,"caps":[[0.5,6.43,"Push: A sends its 7 to B. One message."],[6.68,13.49,"Pull: B asks first, then A replies. Two messages."],[13.74,19.03,"Broadcast: A sends the same 50 MB model to four machines."],[19.28,24.41,"Four copies leave A: 4 × 50 = 200 MB."]],"warp":[[0,0],[0.5,0.4],[6.68,3],[13.74,6],[19.28,8.6],[25.008,11]]},{"dur":30.116,"caps":[[0.5,6.91,"C1 to C4 each hold a number: 3, 5, 2 and 6."],[7.16,12.85,"Reduce sums them: 3, 8, 10, 16."],[13.1,18.71,"Only B gets the total, 16. Four messages."],[18.96,22.41,"All-reduce sums the same four numbers."],[22.66,28.03,"Then 16 goes back to every machine. Eight messages."]],"warp":[[0,0],[0.5,0.4],[7.16,2.6],[13.1,4.8],[18.96,6.8],[22.66,9.2],[30.116,12]]},{"dur":21.572,"caps":[[0.5,4.99,"Wait: B stops until A's signal arrives."],[5.24,8.29,"B sat idle for 6 s."],[8.54,13.75,"Barrier: nobody goes on until all four arrive."],[14,20.09,"They all wait for the slowest: 12 s of idle machines."]],"warp":[[0,0],[0.5,0.4],[5.24,3.3],[8.54,5],[14,8.3],[21.572,11]]},{"dur":26.656,"caps":[[0.5,6.91,"Four rounds: 3 s of computing, then 2 s of sending."],[7.16,14.05,"Stop and wait: the worker sits still while it sends. 20 s."],[14.3,19.91,"Overlap: start the next round while the last result is sent."],[20.16,24.97,"Done in 14 s: 6 s of waiting is hidden."]],"warp":[[0,0],[0.5,0.4],[7.16,2.6],[14.3,5],[20.16,8.2],[26.656,11]]},{"dur":36.548,"caps":[[0.5,5.07,"Three workers, each with the same model, w = 10."],[5.32,10.13,"The minibatch of 6 is split: 2 examples per worker."],[10.38,15.19,"Each worker computes its own gradient: 5, 6 and 4."],[15.44,20.65,"All-reduce: G = 15 lands on every worker."],[20.9,26.99,"Every copy updates the same way: w = 7.5."],[27.24,34.77,"Exactly what one machine gets from all 6: it is minibatch SGD."]],"warp":[[0,0],[0.5,0.4],[5.32,3],[10.38,4.9],[15.44,7],[20.9,9],[27.24,11.4],[36.548,14]]},{"dur":16.788,"caps":[[0.5,6.35,"Each iteration: 3 s of computing, then a 1 s all-reduce."],[6.6,10.05,"While the gradients travel, every worker waits."],[10.3,14.79,"So the workers compute only 75% of the time."]],"warp":[[0,0],[0.5,0.4],[6.6,2.8],[10.3,6],[16.788,9]]},{"dur":21.665,"caps":[[0.5,4.27,"45 points and 3 starting centres."],[4.52,10.29,"Assign each point to the nearest centre, then move each centre to its mean."],[10.54,15.03,"Repeat: points switch cluster and the centres follow."],[15.28,20.41,"Iteration 6: no point switches, so k-means stops."]],"warp":[[0,0],[0.5,0.4],[4.52,2.1],[10.54,4.5],[15.28,8.8],[21.665,12]]},{"dur":23.429,"caps":[[0.5,5.79,"Two mappers get a copy of the centres, 2 and 9."],[6.04,9.17,"Each sample joins its nearest centre."],[9.42,16.39,"Sample 8: 6 from c0, 1 from c1, so it emits ⟨1, 8⟩."],[16.64,22.33,"7 pairs go out: the key is the cluster, the value the sample."]],"warp":[[0,0],[0.5,0.4],[6.04,2.2],[9.42,4.4],[16.64,6.4],[23.429,10]]},{"dur":26.795,"caps":[[0.5,4.99,"The 7 pairs from the map step, grouped by cluster."],[5.24,12.05,"The combiner adds each group up: a sum and a count. 4 records instead of 7."],[12.3,19.67,"Cluster 1: (20 + 14) ÷ (2 + 1) = 11.33, the true mean."],[19.92,25.61,"Local means would give 12: a mean forgets how many points it had."]],"warp":[[0,0],[0.5,0.4],[5.24,2.6],[12.3,4.8],[19.92,7],[26.795,11]]},{"dur":26.843,"caps":[[0.5,3.63,"The reducer adds up the 4 records."],[3.88,11.89,"New centres: 10 ÷ 4 = 2.5 and 34 ÷ 3 = 11.33."],[12.14,16.63,"The centres moved, so they go back to the mappers."],[16.88,20.33,"Next round: no point changes cluster."],[20.58,24.75,"The reducer's test says converged: done."]],"warp":[[0,0],[0.5,0.4],[3.88,2.4],[12.14,4.2],[16.88,6],[20.58,7.8],[26.843,10]]},{"dur":18.343,"caps":[],"warp":[[0,0],[0.5,0.9],[4.52,2],[9.58,3.1],[18.343,9]]}]};
